import { jsPDF } from "jspdf";

const LOGO_B64 = "";

const BLUE     = [26, 74, 153];
const BLACK    = [17, 17, 17];
const GRAY     = [102, 102, 102];
const LGRAY    = [180, 180, 180];
const RULE     = [224, 224, 224];
const WHITE    = [255, 255, 255];

const BIZ = {
  address: "PO Box 00000",
  city:    "City, FL 00000",
  phone:   "(555) 555-5555",
  email:   "contact@ocasiomechanical.com",
};

function fmt(n) {
  return "$" + Number(n || 0).toFixed(2);
}

function get(a, b) {
  return a || b || "";
}

export function generateInvoicePDF(j) {
  const doc  = new jsPDF({ format: "letter", unit: "mm" });
  const W    = 215.9;
  const mL   = 18;
  const mR   = 18;
  const cW   = W - mL - mR;
  const midX = mL + cW / 2;
  let   y    = 14;

  const isLiftTruck = (j.jobType || j.job_type) === "lift_truck";

  // ── LOGO ──────────────────────────────────────────────
  const logoW = 34;
  let logoH = 34;
  try {
    const props = doc.getImageProperties(LOGO_B64);
    logoH = logoW * (props.height / props.width);
    doc.addImage(LOGO_B64, "JPEG", mL, y, logoW, logoH);
  } catch {}

  // ── BUSINESS INFO ─────────────────────────────────────
  doc.setFont("helvetica", "bold");
  doc.setFontSize(13);
  doc.setTextColor(...BLUE);
  doc.text("OCASIO MECHANICAL SERVICES LLC", mL + 38, y + 6);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(...GRAY);
  doc.text("Mobile Mechanical Service  ·  Florida", mL + 38, y + 11);
  doc.text(BIZ.address + "  ·  " + BIZ.city, mL + 38, y + 15.5);
  doc.text(BIZ.phone + "  ·  " + BIZ.email, mL + 38, y + 20);

  // ── RECEIPT LABEL (top right) ─────────────────────────
  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(...LGRAY);
  doc.text("RECEIPT", W - mR, y + 4, { align: "right" });

  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(...BLUE);
  doc.text(get(j.jobNumber, j.job_number), W - mR, y + 10, { align: "right" });

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...LGRAY);
  doc.text(j.date || "", W - mR, y + 16, { align: "right" });

  y += 38;

  // ── DIVIDER ───────────────────────────────────────────
  doc.setDrawColor(...BLUE);
  doc.setLineWidth(0.6);
  doc.line(mL, y, W - mR, y);
  y += 7;

  // ── BILL TO + VEHICLE/LIFT TRUCK ──────────────────────
  const col2X = midX + 4;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7);
  doc.setTextColor(...LGRAY);
  doc.text("BILL TO", mL, y);
  doc.text(isLiftTruck ? "LIFT TRUCK" : "VEHICLE", col2X, y);
  y += 4;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10.5);
  doc.setTextColor(...BLACK);
  doc.text(get(j.customerName, j.customer_name) || "—", mL, y);

  if (isLiftTruck) {
    const ltLabel = (get(j.vehicleMake, j.vehicle_make) + " " + get(j.vehicleModel, j.vehicle_model)).trim() || "—";
    doc.text(ltLabel, col2X, y);
  } else {
    const vLabel = (get(j.vehicleYear, j.vehicle_year) + " " + get(j.vehicleMake, j.vehicle_make) + " " + get(j.vehicleModel, j.vehicle_model)).trim() || "—";
    doc.text(vLabel, col2X, y);
  }
  y += 4.5;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.setTextColor(...GRAY);

  const custLines = [
    get(j.customerPhone, j.customer_phone),
    get(j.customerAddress, j.customer_address),
    get(j.customerCity, j.customer_city)
      ? get(j.customerCity, j.customer_city) + ", FL " + get(j.customerZip, j.customer_zip)
      : "",
  ].filter(Boolean);

  const vehLines = isLiftTruck
    ? [
        get(j.vehicleSerial, j.vehicle_serial) ? "S/N: " + get(j.vehicleSerial, j.vehicle_serial) : "",
        get(j.hourMeter, j.hour_meter) ? "Hour Meter: " + get(j.hourMeter, j.hour_meter) + " hrs" : "",
      ].filter(Boolean)
    : [
        j.mileage ? "Mileage: " + j.mileage : "",
        get(j.vehicleVin, j.vehicle_vin) ? "VIN: " + get(j.vehicleVin, j.vehicle_vin) : "",
      ].filter(Boolean);

  const infoRows = Math.max(custLines.length, vehLines.length);
  for (let i = 0; i < infoRows; i++) {
    if (custLines[i]) doc.text(custLines[i], mL, y);
    if (vehLines[i])  doc.text(vehLines[i],  col2X, y);
    y += 4.5;
  }
  y += 5;

  // ── SERVICE TABLE ─────────────────────────────────────
  const colSvcW  = cW * 0.50;
  const colLabX  = mL + colSvcW;
  const colParX  = colLabX + cW * 0.17;
  const colTotX  = colParX + cW * 0.17;
  const colEnd   = W - mR;

  doc.setDrawColor(...RULE);
  doc.setLineWidth(0.3);
  doc.line(mL, y, colEnd, y);
  y += 4;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7);
  doc.setTextColor(...LGRAY);
  doc.text("SERVICE", mL, y);
  doc.text("LABOR", colLabX + cW * 0.17, y, { align: "right" });
  doc.text("PARTS", colParX + cW * 0.17, y, { align: "right" });
  doc.text("TOTAL", colEnd,               y, { align: "right" });
  y += 3;
  doc.line(mL, y, colEnd, y);
  y += 4.5;

  const lines = j.lines || [];
  for (const l of lines) {
    const lineTotal  = Number(l.labor || 0) + Number(l.parts || 0);
    const svcLines   = doc.splitTextToSize(String(l.service || ""), colSvcW - 4);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(...BLACK);
    svcLines.forEach((sl, si) => doc.text(sl, mL, y + si * 4.5));

    doc.setTextColor(...GRAY);
    doc.text(fmt(l.labor), colLabX + cW * 0.17, y, { align: "right" });
    doc.text(fmt(l.parts), colParX + cW * 0.17, y, { align: "right" });

    doc.setFont("helvetica", "bold");
    doc.setTextColor(...BLACK);
    doc.text(fmt(lineTotal), colEnd, y, { align: "right" });

    y += Math.max(1, svcLines.length) * 4.5 + 1;
    doc.setDrawColor(...RULE);
    doc.setLineWidth(0.2);
    doc.line(mL, y, colEnd, y);
    y += 3;
  }
  y += 3;

  // ── TECHNICIAN NOTES ──────────────────────────────────
  const techNotes = get(j.techNotes, j.tech_notes);
  if (techNotes) {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(7);
    doc.setTextColor(...BLACK);
    doc.text("TECHNICIAN NOTES", mL, y);
    y += 4;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(...GRAY);
    const tnLines = doc.splitTextToSize(techNotes, cW);
    doc.text(tnLines, mL, y);
    y += tnLines.length * 4.5 + 5;
  }

  // ── TOTALS ────────────────────────────────────────────
  const totX = midX + 4;
  const valX = W - mR;

  function row(label, value, bold = false, color = GRAY) {
    doc.setFont("helvetica", bold ? "bold" : "normal");
    doc.setFontSize(bold ? 10 : 9);
    doc.setTextColor(...color);
    doc.text(label, totX, y);
    doc.text(value, valX, y, { align: "right" });
    y += bold ? 5.5 : 4.5;
  }

  row("Labor",          fmt(get(j.labor)));
  row("Parts",          fmt(get(j.parts)));
  row("Tax (7% on parts)", fmt(get(j.tax)));

  // Grand total bar
  doc.setFillColor(...BLUE);
  doc.roundedRect(totX - 2, y, valX - totX + 2, 9, 1.5, 1.5, "F");
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(...WHITE);
  doc.text("GRAND TOTAL", totX + 2, y + 6);
  doc.text(fmt(j.grandTotal || j.grand_total), valX - 2, y + 6, { align: "right" });
  y += 13;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...LGRAY);
  doc.text("Payment: " + get(j.payMethod, j.pay_method), totX, y);
  y += 8;

  // ── SERVICE NOTES ─────────────────────────────────────
  const aiNotes = get(j.aiNotes, j.ai_notes);

  if (aiNotes) {
    const noteLines = doc.splitTextToSize(aiNotes, cW - 8);
    const noteH     = noteLines.length * 4.5 + 6;

    doc.setFillColor(245, 247, 252);
    doc.roundedRect(mL, y, cW, noteH, 2, 2, "F");
    doc.setDrawColor(...BLUE);
    doc.setLineWidth(1.2);
    doc.line(mL, y + 2, mL, y + noteH - 2);

    doc.setFont("helvetica", "italic");
    doc.setFontSize(8.5);
    doc.setTextColor(...GRAY);
    doc.text(noteLines, mL + 5, y + 4.5);
    y += noteH + 5;
  }

  // ── FOOTER ────────────────────────────────────────────
  doc.setDrawColor(...RULE);
  doc.setLineWidth(0.3);
  doc.line(mL, y, W - mR, y);
  y += 6;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(...BLACK);
  doc.text("PAYMENT DUE UPON RECEIPT", W / 2, y, { align: "center" });
  y += 5;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...GRAY);
  doc.text("Make checks payable to: Ocasio Mechanical Services, LLC", W / 2, y, { align: "center" });
  y += 5;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(...BLUE);
  doc.text("Thank You For Your Business!", W / 2, y, { align: "center" });

  return doc.output("blob");
}
    
